let active: AbortController | undefined;
export async function suggestAddress(query: string) {
  active?.abort();
  active = new AbortController();
  const response = await fetch('/api/addresses?q=' + encodeURIComponent(query), {
    signal: active.signal
  });
  if (!response.ok) throw new Error('주소 후보를 가져오지 못했습니다.');
  return response.json();
}

export function validCoordinates(latitude: number, longitude: number) {
  return Number.isFinite(latitude) && Number.isFinite(longitude)
    && latitude >= -90 && latitude <= 90
    && longitude >= -180 && longitude <= 180;
}
// API별 [경도, 위도] 순서와 [위도, 경도] 순서를 확인합니다.

type Point = { id: string; x: number; y: number };
export function gridGroups(points: Point[], cellPixels: number) {
  if (cellPixels <= 0) throw new Error('셀 크기를 확인하세요.');
  const groups = new Map<string, Point[]>();
  for (const point of points) {
    const key = Math.floor(point.x / cellPixels) + ':' + Math.floor(point.y / cellPixels);
    groups.set(key, [...(groups.get(key) || []), point]);
  }
  return [...groups.values()];
}

export function routeUrl(start: [number, number], end: [number, number]) {
  for (const [lng, lat] of [start, end]) {
    if (!Number.isFinite(lng) || !Number.isFinite(lat)
      || Math.abs(lng) > 180 || Math.abs(lat) > 90) throw new Error('좌표 오류');
  }
  return '/api/route?from=' + start.join(',') + '&to=' + end.join(',');
}

type AreaPolicy = { included: Set<string>; excluded: Set<string> };
export function servesPostalCode(policy: AreaPolicy, postalCode: string) {
  const normalized = postalCode.trim();
  return !policy.excluded.has(normalized) && policy.included.has(normalized);
}
